import { isEmpty } from 'lodash-es';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { AutoOnOffRampType, YesOrNo } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

type SettingAutoOnOffRampLocationState = {
  aliasNm?: string;
};

export const SetAutoOnOffRampIntroPage = () => {
  const { state } = useLocation();
  const { navigate } = useNavigate();
  const { aliasNm: routeAliasNm } = (state as SettingAutoOnOffRampLocationState) ?? {};
  const { data: walletList = [] } = useGetCstmrWalletListQuery();

  useSetHeaderTitle(i18n.t('autoOnOffRampSetting'));

  const selectedWallet = walletList.find((wallet) => wallet.aliasNm === routeAliasNm);
  const onRampStatus = walletList.some((wallet) => wallet.dc1AtmcOnrampYn === 'N' || isEmpty(wallet.dc1AtmcOnrampYn))
    ? YesOrNo.아니오
    : YesOrNo.예;
  const offRampStatus = walletList.some((wallet) => wallet.dc1AtmcOfframpYn === 'N' || isEmpty(wallet.dc1AtmcOfframpYn))
    ? YesOrNo.아니오
    : YesOrNo.예;

  // if (!selectedWallet) {
  //   return null;
  // }

  const handleSettingDetail = (selected: AutoOnOffRampType) => () => {
    if (selected === AutoOnOffRampType.자동충전) {
      navigate(`${PATHS.setAutoOnOffRamp.setOnRamp}`, { state: { aliasNm: routeAliasNm } });
    } else {
      navigate(`${PATHS.setAutoOnOffRamp.setOffRamp.root}`, { state: { aliasNm: routeAliasNm } });
    }
  };

  return (
    <div className="content sub setting-auto-on-off-page__content">
      <div className="threshold-toggle-wrapper">
        <div className="toggle-area">
          <div className="toggle-box">
            <p className="toggle-label">{i18n.t('useAutoOnRamp')}</p>
            <p className="auto-on-off-intro-action" onClick={handleSettingDetail(AutoOnOffRampType.자동충전)}>
              {i18n.t('set')}
            </p>
          </div>
          <p className="toggle-info whitespace-pre-wrap">
            {selectedWallet ? (
              <span>
                {selectedWallet.dc1AtmcOnrampYn === YesOrNo.예
                  ? `${i18n.t('text:onRampSetInfo')}`
                  : `${i18n.t('text:onRampNotSetInfo')}`}
              </span>
            ) : onRampStatus === YesOrNo.예 ? (
              <span>{i18n.t('text:onRampSetInfo')}</span>
            ) : (
              <span>{i18n.t('text:onRampNotSetInfo')}</span>
            )}
          </p>
        </div>
      </div>
      <div className="threshold-toggle-wrapper">
        <div className="toggle-area">
          <div className="toggle-box">
            <p className="toggle-label">{i18n.t('useAutoOffRamp')}</p>
            <p className="auto-on-off-intro-action" onClick={handleSettingDetail(AutoOnOffRampType.자동출금)}>
              {i18n.t('set')}
            </p>
          </div>
          <p className="toggle-info whitespace-pre-wrap">
            {selectedWallet ? (
              <span>
                {selectedWallet.dc1AtmcOfframpYn === YesOrNo.예
                  ? `${i18n.t('text:offRampSetInfo')} ${routeAliasNm ? `\n${i18n.t('threshold')} ${(selectedWallet.threshold || 0).toLocaleString()} ${i18n.t('won')}` : ''}`
                  : `${i18n.t('text:offRampNotSetInfo')}`}
              </span>
            ) : offRampStatus === YesOrNo.예 ? (
              <span>{i18n.t('text:offRampSetInfo')}</span>
            ) : (
              <span>{i18n.t('text:offRampNotSetInfo')}</span>
            )}
          </p>
        </div>
      </div>
      <div className="line-box line-2">
        <dl className="info-list">
          <dt>{i18n.t('autoOnOffRampInfo')}</dt>
          <dd>{i18n.t('text:autoOnOffRampExceptionDesc')}</dd>
        </dl>
      </div>
    </div>
  );
};
